angular.module('deciframeApp').controller('SequenciaController', function($http, $window, ngProgressFactory, $anchorScroll, $location, GENEROS, $timeout) {
  var COR_ACORDE = '#2E1C74';
  var vm = this;
  vm.sequenciasFamosas = [];
  vm.minhaSequencia = { acordes: [] };
  vm.isSearching = false;
  vm.showSearchResultsCount = false;
  vm.esfigeSpeech = "";
  vm.musics = [];
  vm.generos = GENEROS;
  vm.meuGenero = "";
  vm.progressbar = ngProgressFactory.createInstance();

  vm.carregandoSequencias = false;
  vm.erroSequencias = "";
  vm.novaSequencia = "";
  vm.isCadastrando = false;
  vm.mensagemCadastro = "";
  vm.erroCadastro = "";
  vm.cadastroAberto = false;

  var paraSequencia = function(item) {
    return {
      id: item.id,
      acordes: item.acordes.map(function(acorde) {
        return { acorde: acorde, cor: COR_ACORDE };
      })
    };
  };

  var selecionarSequencia = function(id) {
    for (var i = 0; i < vm.sequenciasFamosas.length; i++) {
      if (vm.sequenciasFamosas[i].id === id) {
        vm.pesquisarPorSequencia(vm.sequenciasFamosas[i]);
        return;
      }
    }
  };

  var nomeSequencia = function(sequencia) {
    if (sequencia && sequencia.acordes && sequencia.acordes.length) {
      return sequencia.acordes.join(',');
    }
    return (vm.novaSequencia || '').trim();
  };

  var carregarSequencias = function(idParaSelecionar) {
    vm.carregandoSequencias = true;
    vm.erroSequencias = "";
    $http.get('sequencias')
      .success(function(data) {
        vm.carregandoSequencias = false;
        vm.sequenciasFamosas = data.map(paraSequencia);
        if (idParaSelecionar) {
          selecionarSequencia(idParaSelecionar);
        }
      })
      .error(function() {
        vm.carregandoSequencias = false;
        vm.erroSequencias = "Não foi possível carregar as sequências.";
      });
  };

  vm.isSequenciaSelecionada = function(sequencia) {
    return !!sequencia && !!vm.minhaSequencia &&
      vm.minhaSequencia.id === sequencia.id;
  };

  vm.toggleCadastro = function() {
    vm.cadastroAberto = !vm.cadastroAberto;
    if (!vm.cadastroAberto) {
      return;
    }
    $timeout(function() {
      var campo = $window.document.getElementById('nova-sequencia');
      if (campo) {
        campo.focus();
      }
    }, 0);
  };

  vm.cadastrarSequencia = function() {
    if (!vm.novaSequencia || !vm.novaSequencia.trim()) {
      vm.erroCadastro = "Informe os acordes da sequência.";
      vm.mensagemCadastro = "";
      return;
    }

    vm.isCadastrando = true;
    vm.erroCadastro = "";
    vm.mensagemCadastro = "";
    $http.post('sequencias', { acordes: vm.novaSequencia })
      .success(function(data, status) {
        var acordes = nomeSequencia(data);
        vm.isCadastrando = false;
        vm.mensagemCadastro = status === 201 ?
          "Sequência " + acordes + " cadastrada." :
          "Sequência " + acordes + " já estava cadastrada.";
        vm.novaSequencia = "";
        carregarSequencias(data.id);
      })
      .error(function(data) {
        vm.isCadastrando = false;
        vm.erroCadastro = (data && data.erro) ?
          data.erro :
          "Não foi possível cadastrar a sequência.";
      });
  };

  vm.pesquisarPorSequencia = function(sequencia) {
    if (sequencia) {
      vm.minhaSequencia = sequencia;
    }
    if (!vm.minhaSequencia.id) {
      return;
    }

    vm.progressbar.start();
